@code {
    private AppointmentModel Model { get; set; } = new();
    private bool _showStep2;
    private bool _availabilityChecked;
    private bool _booked;
    private List<string> _doctors = new();
    private List<string> _timeSlots = new();

    private string? _emailError;
    private string? _doctorError;
    private string? _timeSlotError;

    private EditContext? _editContext;

    protected override async Task OnInitializedAsync()
    {
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        _editContext = new EditContext(Model);
        _editContext.EnableDataAnnotationsValidation();

        if (_editContext.Validate())
        {
            // Only proceed if step 1 fields are valid
            var step1Valid = !_editContext.GetValidationMessages(() => Model.PatientName).Any()
                         && !_editContext.GetValidationMessages(() => Model.Email).Any()
                         && !_editContext.GetValidationMessages(() => Model.Phone).Any()
                         && !_editContext.GetValidationMessages(() => Model.InsuranceProvider).Any();

            if (step1Valid)
            {
                _showStep2 = true;
            }
        }
        else
        {
            // Check only step 1 fields
            var step1Valid = !_editContext.GetValidationMessages(() => Model.PatientName).Any()
                         && !_editContext.GetValidationMessages(() => Model.Email).Any()
                         && !_editContext.GetValidationMessages(() => Model.Phone).Any()
                         && !_editContext.GetValidationMessages(() => Model.InsuranceProvider).Any();

            if (step1Valid)
            {
                _showStep2 = true;
            }
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        _availabilityChecked = false;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
    }

    private async Task CheckAvailability()
    {
        ClearServerErrors();
        _availabilityChecked = false;

        if (string.IsNullOrEmpty(Model.Doctor) || !Model.AppointmentDate.HasValue
            || string.IsNullOrEmpty(Model.TimeSlot) || string.IsNullOrEmpty(Model.ReasonForVisit))
        {
            return;
        }

        if (Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            return;
        }

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        if (errors.Count > 0)
        {
            if (errors.TryGetValue("email", out var emailErr))
                _emailError = emailErr;
            if (errors.TryGetValue("doctor", out var doctorErr))
                _doctorError = doctorErr;
            if (errors.TryGetValue("timeSlot", out var timeSlotErr))
                _timeSlotError = timeSlotErr;
        }
        else
        {
            _availabilityChecked = true;
        }
    }

    private void ClearServerErrors()
    {
        _emailError = null;
        _doctorError = null;
        _timeSlotError = null;
    }

    private void HandleSubmit()
    {
        if (_availabilityChecked)
        {
            _booked = true;
        }
    }
}
"}

